SELECT id, reference_signal_id, evaluation_path, evaluated_at, replay_mode, five_minute_signal_id, five_minute_raw_decision, five_minute_effective_decision, five_minute_candle_close_time, five_minute_age_seconds, one_hour_signal_id, one_hour_raw_decision, one_hour_effective_decision, one_hour_age_seconds, assessment_band, max_initial_percent, final_result, LEFT(final_reason, 300) AS final_reason_300 FROM crypto_ai.buy_htf_assessment_audit WHERE reference_signal_id IN (156723,159408,165412,165415,167668,171589,176710) ORDER BY evaluated_at, id LIMIT 60